type PageRequest = {
  queryKey: string;
  filters: Readonly<Record<string, string | readonly string[]>>;
  sort: string;
  limit: number;
  cursor?: string;
  signal: AbortSignal;
};

type PageResult<T> = {
  items: readonly T[];
  nextCursor?: string;
  orderingVersion?: string;
};

interface PageLoader<T> {
  load(input: PageRequest): Promise<PageResult<T>>;
}
